"""More variety for the most-practised A2 topics (teacher, 28 October: learners start to meet the same tasks again).
12 new tasks per topic, like the ones that worked well. Rules kept from the earlier reviews: every wrong option is
ungrammatical; one natural answer (no gap where another word from the instruction also fits, no tense left open);
"—" for no preposition / no article; a Latvian reason only where Latvian leads to the mistake."""
from lib import *

NONE = "—"
def ex(en, lv): return (en, lv)

# ── Subject and verb ──
S_ONE = ex("One person or thing (*he / she / it*) + verb-*s*: *My brother lives in Oslo.*", "Viens (*he / she / it*) + darbības vārds ar -s: *My brother lives in Oslo.*")
S_MORE = ex("More than one + verb without *-s*: *My parents have a shop.*", "Vairāki + darbības vārds bez -s: *My parents have a shop.*")
S_EVERY = ex("*everybody, nobody, every* + verb-*s*: *Everybody speaks English.*", "Latviski \"visi runā\" ir daudzskaitlī, bet *everybody* ir vienskaitlī: *Everybody speaks English.*")
S_MAIN = ex("The verb agrees with the main noun: *One of my friends works…*", "Darbības vārds saskan ar galveno lietvārdu: *One of my friends works…*")
S_PEOPLE = ex("*people, children, police* are plural: *The people are friendly.*", "*people, children, police* ir daudzskaitlī: *The people are friendly.*")
S_NEWS = ex("*news* is singular: *The news is good.*", "Latviski \"ziņas\" ir daudzskaitlī, bet *news* ir vienskaitlī: *The news is good.*")
T = Topic("Subject and verb (my friend lives, my friends live)", mcq_b=2, text_b=3, mcq=S_ONE, bank=S_ONE, gap=S_ONE, text=S_ONE, order=S_ONE, match=S_ONE)
T.mcq("A2.1", "Choose the correct option: My brother ___ in Oslo.", "lives", ["live", "living"], S_ONE, b=1)
T.mcq("A2.1", "Choose the correct option: My parents ___ a small shop.", "have", ["has", "having"], S_MORE, b=1)
T.mcq("A2.1", "Choose the correct option: Everybody in my class ___ English.", "speaks", ["speak", "speaking"], S_EVERY)
T.mcq("A2.2", "Choose the correct option: One of my friends ___ in a hospital.", "works", ["work", "working"], S_MAIN)
T.mcq("A2.2", "Choose the correct option: The people next door ___ very friendly.", "are", ["is", "be"], S_PEOPLE)
T.mcq("A2.2", "Choose the correct option: Nobody ___ the answer.", "knows", ["know", "knowing"], S_EVERY)
T.gap("A2.1", "Use the present simple: My grandmother ___ TV every evening. (watch)", "watches", S_ONE)
T.gap("A2.1", "Use the present simple: Anna and her sister ___ to the gym every Friday. (go)", "go", S_MORE)
T.gap("A2.2", "Use the present simple: The news ___ good today. (be)", "is", S_NEWS)
T.text("A2.2", "Correct the mistake: My sister work in a bank.", "My sister works in a bank.", S_ONE)
T.text("A2.2", "Correct the mistake: The children is in the garden.", "The children are in the garden.", S_PEOPLE)
T.order("A2.1", "my best friend lives near the station", why=S_ONE)

# ── Prepositions after words ──
D_GEN = ex("Some words always take the same preposition: learn them in pairs.", "Daži vārdi vienmēr lieto vienu un to pašu prievārdu: tos mācās pa pāriem.")
D_FOR = ex("*wait for*: *I'm waiting for the bus.*", "*wait for*: *I'm waiting for the bus.*")
D_AT = ex("*good at*: *She's good at maths.*", "Latviski \"viņai padodas matemātika\", bet angliski *good at*: *She's good at maths.*")
D_NONE = ex("*call, discuss, enter* take no preposition: *Call me later.*", "Latviski \"zvanīt kādam, apspriest par\", bet angliski *call, discuss* bez prievārda: *Call me later.*")
D_TO = ex("*belong to, listen to, married to*: *This bag belongs to my sister.*", "*belong to, listen to, married to*: *This bag belongs to my sister.*")
D_OF = ex("*afraid of*: *Are you afraid of spiders?*", "Latviski \"baidīties no\", tāpēc gribas *from*, bet angliski *afraid of*: *Are you afraid of spiders?*")
D_ON = ex("*depend on*: *It depends on the weather.*", "Latviski \"atkarīgs no\", tāpēc gribas *from*, bet angliski *depend on*: *It depends on the weather.*")
D_IN = ex("*interested in*: *I'm interested in history.*", "Latviski \"interesēties par\", bet angliski *interested in*: *I'm interested in history.*")
T = Topic("Prepositions after words (listen to, good at)", mcq_b=2, text_b=3, mcq=D_GEN, bank=D_GEN, gap=D_GEN, text=D_GEN, order=D_GEN, match=D_GEN)
T.mcq("A2.1", "Choose the correct option: I'm waiting ___ my friend.", "for", ["to", "on"], D_FOR, b=1)
T.mcq("A2.1", "Choose the correct option: She's very good ___ maths.", "at", ["in", "on"], D_AT, b=1)
T.mcq("A2.1", "Choose the correct option: Please answer ___ my question.", NONE, ["to", "on"], ex("*answer, call, discuss* take no preposition: *Answer my question.*", "Latviski \"atbildēt uz\", bet angliski *answer* bez prievārda: *Answer my question.*"))
T.mcq("A2.2", "Choose the correct option: This bag belongs ___ my sister.", "to", ["at", "for"], D_TO)
T.mcq("A2.2", "Choose the correct option: We discussed ___ the plan for an hour.", NONE, ["about", "on"], D_NONE)
T.mcq("A2.2", "Choose the correct option: Are you afraid ___ spiders?", "of", ["from", "at"], D_OF)
T.gap("A2.1", "Write the preposition: I often listen ___ music in the car.", "to", D_TO)
T.gap("A2.2", "Write the preposition: It depends ___ the price.", "on", D_ON)
T.gap("A2.2", "Write the preposition: She's married ___ a doctor.", "to", ex("*married to*: *She's married to a doctor.*", "Latviski \"precējusies ar\", tāpēc gribas *with*, bet angliski *married to*."))
T.gap("A2.2", "Write the preposition: I'm interested ___ history.", "in", D_IN)
T.text("A2.2", "Correct the mistake: I'm waiting you outside.", "I'm waiting for you outside.", D_FOR)
T.order("A2.2", "what is she talking about", why=ex("A preposition often goes at the end of a question: *What is she talking about?*", "Jautājumā prievārds bieži ir beigās: *What is she talking about?*"), cue="Put the words in order to make a question.")

# ── Quantity ──
Q_ANY = ex("*any* in questions and negatives: *There isn't any milk.*", "*any* jautājumos un noliegumos: *There isn't any milk.*")
Q_MANY = ex("*many* + plural, *much* + uncountable: *How many people? How much money?*", "*many* + daudzskaitlis, *much* + nesaskaitāms: *How many people? How much money?*")
Q_FEW = ex("*a few* + plural, *a little* + uncountable: *a few friends, a little time.*", "*a few* + daudzskaitlis, *a little* + nesaskaitāms: *a few friends, a little time.*")
Q_TOO = ex("*too much* + uncountable, *too many* + plural; *enough* after an adjective: *big enough.*", "*too much* + nesaskaitāms, *too many* + daudzskaitlis; *enough* aiz īpašības vārda: *big enough.*")
T = Topic("Quantity: some, any, much, many, enough", mcq_b=2, text_b=3, mcq=Q_MANY, bank=Q_MANY, gap=Q_MANY, text=Q_MANY, order=Q_MANY, match=Q_MANY)
T.mcq("A2.2", "Choose the correct option: There isn't ___ milk in the fridge.", "any", ["some", "many"], Q_ANY)
T.mcq("A2.2", "Choose the correct option: How ___ people came to the party?", "many", ["much", "lot"], ex("*many* + plural: *How many people?*", "Latviski abos gadījumos \"cik\", bet ar daudzskaitli angliski *many*: *How many people?*"))
T.mcq("A2.2", "Choose the correct option: We've got ___ time, so let's have a coffee.", "a little", ["a few", "many"], Q_FEW)
T.mcq("A2.2", "Choose the correct option: I have ___ good friends at work.", "a few", ["a little", "much"], Q_FEW)
T.mcq("B1.1", "Choose the correct option: I can't sleep. There's ___ noise outside.", "too much", ["too many", "enough of"], Q_TOO)
T.mcq("B1.1", "Choose the correct option: We need two more chairs. There aren't ___.", "enough", ["too much", "enough of"], Q_TOO)
T.gap("A2.2", "Write much or many: How ___ money do you need?", "much", Q_MANY)
T.gap("A2.2", "Write much or many: How ___ brothers have you got?", "many", Q_MANY)
T.gap("B1.1", "Write the missing word: Is the room big ___ for ten people?", "enough", Q_TOO)
T.gap("B1.1", "Write the missing word: There were ___ many cars, so we took the bus.", "too | so", Q_TOO)
T.text("A2.2", "Correct the mistake: How much people work here?", "How many people work here?", Q_MANY)
T.text("B1.1", "Correct the mistake: There aren't some apples left.", "There aren't any apples left.", Q_ANY)

# ── Articles ──
A_AN = ex("Jobs take *a / an*; *an* before a vowel sound: *She's an engineer.*", "Latviešu valodā artikulu nav, tāpēc tos izlaiž, bet profesijām vajag *a / an*: *She's an engineer.*")
A_THE2 = ex("*the* the second time: *I saw a cat. The cat was black.*", "*the*, kad pieminam otro reizi: *I saw a cat. The cat was black.*")
A_ONLY = ex("*the* with the only one and with superlatives: *the Moon, the best.*", "Latviski \"mēness\" bez artikula, bet vienīgajam un ar \"vis-\" vajag *the*: *the Moon, the best.*")
A_NO = ex("No article with meals and with places used for their purpose: *have lunch, go to bed.*", "Bez artikula ēdienreizēm un vietām, ko lieto to nolūkam: *have lunch, go to bed.*")
A_RIVER = ex("*the* with rivers and seas: *the Danube, the Baltic Sea.*", "*the* ar upēm un jūrām: *the Danube, the Baltic Sea.*")
T = Topic("Articles", mcq_b=2, text_b=3, mcq=A_AN, bank=A_AN, gap=A_AN, text=A_AN, order=A_AN, match=A_AN)
T.mcq("A2.2", "Choose the correct option: My sister is ___ engineer.", "an", ["a", "the"], A_AN)
T.mcq("A2.2", "Choose the correct option: We usually have ___ lunch at one.", NONE, ["a", "the"], A_NO)
T.mcq("A2.2", "Choose the correct option: I saw a cat in the garden. ___ cat was black.", "The", ["A", NONE], A_THE2)
T.mcq("B1.1", "Choose the correct option: ___ Moon goes round the Earth.", "The", ["A", NONE], A_ONLY)
T.mcq("B1.1", "Choose the correct option: She's ___ best student in the class.", "the", ["a", NONE], A_ONLY)
T.mcq("B1.1", "Choose the correct option: She speaks ___ English very well.", NONE, ["the", "an"], ex("No article with languages: *She speaks English.*", "Valodām artikulu nelieto: *She speaks English.*"))
T.gap("A2.2", "Write a or an: I need ___ umbrella. It's raining.", "an", ex("*an* before a vowel sound: *an umbrella.*", "*an* pirms patskaņa skaņas: *an umbrella.*"))
T.gap("A2.2", "Write a or an: My father is ___ taxi driver.", "a", A_AN)
T.gap("B1.1", "Write the missing word: ___ Danube flows into the Black Sea.", "The", A_RIVER)
T.text("B1.1", "Correct the mistake: She is nurse in a hospital.", "She is a nurse in a hospital.", A_AN)
T.text("B1.1", "Correct the mistake: I'm learning the Spanish at evening classes.", "I'm learning Spanish at evening classes.", ex("No article with languages: *I'm learning Spanish.*", "Valodām artikulu nelieto: *I'm learning Spanish.*"))
T.order("A2.2", "she is an english teacher", why=A_AN)

# ── Irregular plurals ──
P_NEW = ex("Some plurals are new words: *woman → women, child → children, person → people.*", "Dažiem lietvārdiem daudzskaitlis ir cits vārds: *woman → women, child → children, person → people.*")
P_VOW = ex("Some plurals change the vowel: *tooth → teeth, foot → feet, mouse → mice.*", "Dažiem daudzskaitlī mainās patskanis: *tooth → teeth, foot → feet, mouse → mice.*")
P_F = ex("*-f / -fe* → *-ves*: *knife → knives.*", "*-f / -fe* → *-ves*: *knife → knives.*")
P_SAME = ex("*sheep* and *fish* are the same in the plural: *fifty sheep.*", "*sheep* un *fish* daudzskaitlī nemainās: *fifty sheep.*")
P_Y = ex("Consonant + *-y* → *-ies*: *city → cities.*", "Līdzskanis + *-y* → *-ies*: *city → cities.*")
T = Topic("Irregular plurals (children, people, men, teeth)", mcq_b=1, text_b=3, mcq=P_NEW, bank=P_NEW, gap=P_NEW, text=P_NEW, order=P_NEW, match=P_NEW)
T.mcq("A2.1", "Choose the correct option: There are three ___ in the photo.", "women", ["womans", "woman"], P_NEW)
T.mcq("A2.1", "Choose the correct option: The dentist checked all my ___.", "teeth", ["tooths", "tooth"], P_VOW)
T.mcq("A2.1", "Choose the correct option: I have two ___ and ten toes.", "feet", ["foots", "feets"], P_VOW)
T.mcq("A2.2", "Choose the correct option: How many ___ live in your flat?", "people", ["peoples", "person"], P_NEW)
T.mcq("A2.2", "Choose the correct option: We need two sharp ___.", "knives", ["knifes", "knive"], P_F)
T.gap("A2.1", "Write the plural: one child, two ___", "children", P_NEW)
T.gap("A2.1", "Write the plural: one man, three ___", "men", P_NEW)
T.gap("A2.2", "There are lots of ___ in the old house. (mouse)", "mice", P_VOW)
T.gap("A2.2", "The farmer has fifty ___. (sheep)", "sheep", P_SAME)
T.gap("A2.2", "Riga and Tallinn are beautiful ___. (city)", "cities", P_Y)
T.text("A2.2", "Correct the mistake: The childrens are playing outside.", "The children are playing outside.", P_NEW)
T.order("A2.2", "the police are looking for him", why=ex("*police* is always plural: *The police are…*", "*police* vienmēr ir daudzskaitlī: *The police are…*"))

# ── In, on, at ──
I_AT = ex("*at* + a clock time: *at eight o'clock.*", "*at* + pulksteņa laiks: *at eight o'clock.*")
I_IN = ex("*in* + a month, year, season or part of the day: *in February, in the morning.*", "*in* + mēnesis, gads, gadalaiks vai dienas daļa: *in February, in the morning.*")
I_ON = ex("*on* + a day or a date: *on 12 June, on Sundays.*", "*on* + diena vai datums: *on 12 June, on Sundays.*")
I_NO = ex("No preposition before *next / last / this / every*: *see you next week.*", "Bez prievārda pirms *next / last / this / every*: *see you next week.*")
I_SURF = ex("*on* + a surface: *on the wall.*", "Latviski \"pie sienas\", bet angliski *on the wall*: *on* = uz virsmas.")
I_POINT = ex("*at* + a point or a place where you do something: *at home, at the bus stop.*", "*at* + punkts vai vieta, kur kaut ko dara: *at home, at the bus stop.*")
I_INSIDE = ex("*in* = inside, or a town or country: *in my bag, in Riga.*", "*in* = iekšā, vai pilsēta vai valsts: *in my bag, in Riga.*")
T = Topic("Prepositions of time and place (in, on, at)", mcq_b=2, text_b=3, mcq=I_IN, bank=I_IN, gap=I_IN, text=I_IN, order=I_IN, match=I_IN)
T.mcq("A2.1", "Choose the correct option: The film starts ___ eight o'clock.", "at", ["in", "on"], I_AT, b=1)
T.mcq("A2.1", "Choose the correct option: We go skiing ___ February.", "in", ["on", "at"], I_IN, b=1)
T.mcq("A2.1", "Choose the correct option: My brother was born ___ 12 June.", "on", ["in", "at"], I_ON)
T.mcq("A2.2", "Choose the correct option: I'll see you ___ next week.", NONE, ["on", "in"], I_NO)
T.mcq("A2.2", "Choose the correct option: There's a big picture ___ the wall.", "on", ["in", "at"], I_SURF)
T.mcq("A2.2", "Choose the correct option: I'll meet you ___ the bus stop.", "at", ["in", "on"], I_POINT)
T.gap("A2.1", "Write in, on or at: The shop is closed ___ Sundays.", "on", I_ON)
T.gap("A2.1", "Write in, on or at: I always drink coffee ___ the morning.", "in", I_IN)
T.gap("A2.2", "Write in, on or at: The keys are ___ my bag.", "in", I_INSIDE)
T.gap("A2.2", "Write in, on or at: We arrived ___ Riga late at night.", "in", ex("*arrive in* + a city or country: *We arrived in Riga.*", "Latviski \"atbraucām uz Rīgu\", tāpēc gribas *to*, bet angliski *arrive in* + pilsēta."))
T.gap("A2.2", "Write in, on or at: She works ___ home on Fridays.", "at", I_POINT)
T.text("A2.2", "Correct the mistake: See you on next Friday.", "See you next Friday.", I_NO)

# ── Past simple ──
PA_DID = ex("*did* + base verb: *Did you see it? I didn't like it.*", "*did* + pamatforma: *Did you see it? I didn't like it.*")
PA_IRR = ex("Irregular verbs have their own past form: *go → went, buy → bought, have → had.*", "Nekārtnajiem darbības vārdiem ir sava pagātnes forma: *go → went, buy → bought, have → had.*")
PA_WAS = ex("*be* in the past: *was / were*, no *did*: *Were you at home?*", "*be* pagātnē: *was / were*, bez *did*: *Were you at home?*")
PA_AGO = ex("A finished time (*ago, yesterday, last…*) needs the past simple: *She lost her keys two days ago.*", "Pabeigtam laikam (*ago, yesterday, last…*) vajag Past Simple: *She lost her keys two days ago.*")
PA_REG = ex("Regular verbs + *-ed*: *walk → walked.*", "Kārtnie darbības vārdi + *-ed*: *walk → walked.*")
T = Topic("Past simple", mcq_b=2, text_b=3, mcq=PA_DID, bank=PA_DID, gap=PA_IRR, text=PA_DID, order=PA_IRR, match=PA_IRR)
T.mcq("A2.1", "Choose the correct option: Did you ___ the news last night?", "see", ["saw", "seen"], PA_DID, b=1)
T.mcq("A2.1", "Choose the correct option: We ___ to Spain last summer.", "went", ["goed", "gone"], PA_IRR, b=1)
T.mcq("A2.1", "Choose the correct option: I ___ like the film. It was boring.", "didn't", ["don't", "wasn't"], PA_DID)
T.mcq("A2.2", "Choose the correct option: ___ you at home yesterday evening?", "Were", ["Did", "Was"], PA_WAS)
T.mcq("A2.2", "Choose the correct option: She ___ her keys two days ago.", "lost", ["losed", "has lost"], PA_AGO)
T.gap("A2.1", "I ___ a new phone last week. (buy)", "bought", PA_IRR)
T.gap("A2.1", "They ___ dinner at nine yesterday. (have)", "had", PA_IRR)
T.gap("A2.2", "She ___ the bus yesterday morning. (not / catch)", "didn't catch | did not catch", PA_DID)
T.gap("A2.2", "Where ___ you ___ your holiday last year? (spend)", "did / spend", PA_DID)
T.gap("A2.2", "We ___ in the park for two hours yesterday. (walk)", "walked", PA_REG)
T.text("A2.2", "Make a question: You saw Tom yesterday.", "Did you see Tom yesterday?", PA_DID)
T.text("A2.2", "Make it negative: He came to the party.", "He didn't come to the party. | He did not come to the party.", PA_DID)

# ── Present simple ──
PS_DOES = ex("*he / she / it*: *doesn't* + base verb: *My sister doesn't drink coffee.*", "*he / she / it*: *doesn't* + pamatforma: *My sister doesn't drink coffee.*")
PS_DO = ex("*I / you / we / they*: *do / don't*: *Do your parents live here?*", "*I / you / we / they*: *do / don't*: *Do your parents live here?*")
PS_S = ex("*he / she / it* + verb-*s*: *He goes to work by bus.*", "*he / she / it* + darbības vārds ar -s: *He goes to work by bus.*")
PS_Q = ex("A question with *does* for *he / she / it*: *What time does the film start?*", "Jautājums ar *does* (*he / she / it*): *What time does the film start?*")
T = Topic("Present simple", mcq_b=2, text_b=3, mcq=PS_S, bank=PS_S, gap=PS_S, text=PS_S, order=PS_S, match=PS_S)
T.mcq("A2.1", "Choose the correct option: My sister ___ coffee.", "doesn't drink", ["don't drink", "doesn't drinks"], PS_DOES, b=1)
T.mcq("A2.1", "Choose the correct option: ___ your parents live in Riga?", "Do", ["Does", "Are"], PS_DO, b=1)
T.mcq("A2.1", "Choose the correct option: He ___ to work by bus.", "goes", ["go", "going"], PS_S)
T.mcq("A2.2", "Choose the correct option: What time ___ the film start?", "does", ["do", "is"], PS_Q)
T.gap("A2.1", "She ___ English and German. (speak)", "speaks", PS_S)
T.gap("A2.1", "We ___ meat. We're vegetarians. (not / eat)", "don't eat | do not eat", PS_DO)
T.gap("A2.2", "How often ___ you ___ your grandparents? (visit)", "do / visit", PS_DO)
T.gap("A2.2", "My brother ___ his homework after dinner. (do)", "does", PS_S)
T.text("A2.2", "Make it negative: She likes cats.", "She doesn't like cats. | She does not like cats.", PS_DOES)
T.text("A2.2", "Make a question: He works at the weekend.", "Does he work at the weekend?", PS_Q)
T.order("A2.1", "my father never drinks coffee", why=ex("*never* goes before the main verb: *My father never drinks coffee.*", "*never* ir pirms pamatdarbības vārda: *My father never drinks coffee.*"))
T.order("A2.2", "where does your sister work", why=PS_Q, cue="Put the words in order to make a question.")

# ── Adverbs ──
AD_LY = ex("An adverb says how: adjective + *-ly*: *careful → carefully.*", "Apstākļa vārds saka, kā: īpašības vārds + *-ly*: *careful → carefully.*")
AD_WELL = ex("*good → well*: *He speaks Spanish well.*", "*good → well*: *He speaks Spanish well.*")
AD_BE = ex("Frequency adverbs go after *be*: *I am never late.*", "Biežuma apstākļa vārdi ir aiz *be*: *I am never late.*")
AD_ADJ = ex("After *look, feel, seem, sound*: an adjective: *You look tired.*", "Aiz *look, feel, seem, sound* ir īpašības vārds: *You look tired.*")
AD_ABS = ex("Strong adjectives take *absolutely*, not *very*: *absolutely amazing.*", "Ar stipriem īpašības vārdiem *absolutely*, nevis *very*: *absolutely amazing.*")
AD_HARD = ex("*hard* = with effort, *hardly* = almost not: *I can hardly hear you.*", "*hard* = ar piepūli, *hardly* = gandrīz nemaz: *I can hardly hear you.*")
T = Topic("Adverbs: manner, frequency, degree", mcq_b=2, text_b=3, mcq=AD_LY, bank=AD_LY, gap=AD_LY, text=AD_LY, order=AD_BE, match=AD_LY)
T.mcq("A2.2", "Choose the correct option: She drives very ___.", "carefully", ["careful", "carefuly"], AD_LY)
T.mcq("A2.2", "Choose the correct option: He speaks Spanish ___.", "well", ["good", "goodly"], AD_WELL)
T.mcq("A2.2", "Choose the correct option: I ___ late for work.", "am never", ["never am", "never be"], AD_BE)
T.mcq("A2.2", "Choose the correct option: You look ___ today.", "tired", ["tiredly", "tire"], AD_ADJ)
T.mcq("B1.1", "Choose the correct option: The view from the tower was ___ amazing.", "absolutely", ["very", "much"], AD_ABS)
T.gap("A2.2", "Please speak ___. The baby is sleeping. (quiet)", "quietly", AD_LY)
T.gap("A2.2", "He works very ___ every day. (hard)", "hard", ex("*hard* has no *-ly* form when it means *with effort*: *He works hard.*", "*hard* nozīmē \"ar piepūli\" un ir bez -ly: *He works hard.*"))
T.gap("B1.1", "I can ___ hear you. Please speak up. (hard)", "hardly", AD_HARD)
T.text("A2.2", "Correct the mistake: She sings very good.", "She sings very well.", AD_WELL)
T.text("A2.2", "Correct the mistake: I very like this song.", "I like this song very much. | I really like this song.", ex("*very* cannot describe a verb: *I like it very much.*", "Latviski \"ļoti patīk\", bet angliski *very* viens pats nevar aprakstīt darbības vārdu: *I like it very much.*"))
T.order("A2.2", "we usually have breakfast at seven", why=ex("Frequency adverbs go before the main verb: *We usually have breakfast…*", "Biežuma apstākļa vārdi ir pirms pamatdarbības vārda: *We usually have breakfast…*"))
T.order("B1.1", "she has never been to paris", why=ex("With two verbs, the adverb goes after the first: *He has never been…*", "Ja ir divi darbības vārdi, apstākļa vārds ir aiz pirmā: *He has never been…*"))

# ── Verb patterns ──
V_ING = ex("*enjoy, finish, mind* + *-ing*: *I enjoy swimming.*", "*enjoy, finish, mind* + *-ing*: *I enjoy swimming.*")
V_TO = ex("*want, decide, hope* + *to*: *We decided to buy a car.*", "*want, decide, hope* + *to*: *We decided to buy a car.*")
V_PREP = ex("After a preposition: *-ing*: *looking forward to seeing, thank you for helping.*", "Aiz prievārda: *-ing*: *looking forward to seeing, thank you for helping.*")
V_MAKE = ex("*make / let* + person + base verb: *She made me laugh.*", "*make / let* + cilvēks + pamatforma: *She made me laugh.*")
T = Topic("Verb patterns: -ing or to", mcq_b=2, text_b=3, mcq=V_ING, bank=V_ING, gap=V_ING, text=V_ING, order=V_ING, match=V_ING)
T.mcq("A2.2", "Choose the correct option: I enjoy ___ in the sea.", "swimming", ["to swim", "swim"], V_ING)
T.mcq("A2.2", "Choose the correct option: We decided ___ a new car.", "to buy", ["buying", "buy"], V_TO)
T.mcq("A2.2", "Choose the correct option: Do you want ___ with us?", "to come", ["coming", "come"], V_TO)
T.mcq("B1.1", "Choose the correct option: I'm looking forward to ___ you.", "seeing", ["see", "to see"], V_PREP)
T.mcq("B1.1", "Choose the correct option: The film made me ___.", "laugh", ["to laugh", "laughing"], V_MAKE)
T.gap("A2.2", "He finished ___ the report at six. (write)", "writing", V_ING)
T.gap("A2.2", "I hope ___ you again soon. (see)", "to see", V_TO)
T.gap("B1.1", "Thank you for ___ me with the boxes. (help)", "helping", V_PREP)
T.gap("B1.1", "Would you mind ___ the window? (open)", "opening", V_ING)
T.text("B1.1", "Correct the mistake: I want that you come with me.", "I want you to come with me.", ex("*want* + person + *to*: *I want you to come.*", "Latviski \"gribu, lai tu atnāc\", tāpēc rodas *that*, bet angliski *want* + cilvēks + *to*: *I want you to come.*"))
T.text("B1.1", "Correct the mistake: She is good at draw.", "She is good at drawing.", V_PREP)
T.order("A2.2", "they decided to stay at home", why=V_TO)

# ── Comparison ──
C_ER = ex("Short adjectives: *-er* + *than*: *taller than.*", "Īsi īpašības vārdi: *-er* + *than*: *taller than.*")
C_MORE = ex("Long adjectives: *more* + adjective: *more expensive than.*", "Gari īpašības vārdi: *more* + īpašības vārds: *more expensive than.*")
C_BEST = ex("Irregular: *good → better → the best.*", "Nekārtni: *good → better → the best.*")
C_EST = ex("Superlative: *the* + *-est*: *the hottest day.*", "Vispārākā pakāpe: *the* + *-est*: *the hottest day.*")
C_AS = ex("*the same as*: *Your bag is the same as mine.*", "*the same as*: *Your bag is the same as mine.*")
T = Topic("Comparison: -er, more, the most, as ... as", mcq_b=2, text_b=3, mcq=C_ER, bank=C_ER, gap=C_ER, text=C_ER, order=C_ER, match=C_ER)
T.mcq("A2.1", "Choose the correct option: My brother is ___ than me.", "taller", ["more tall", "tallest"], C_ER, b=1)
T.mcq("A2.1", "Choose the correct option: This is the ___ restaurant in town.", "best", ["goodest", "better"], C_BEST)
T.mcq("A2.2", "Choose the correct option: Today is ___ than yesterday.", "colder", ["more cold", "coldest"], C_ER)
T.mcq("A2.2", "Choose the correct option: This phone is ___ expensive than that one.", "more", ["most", "the most"], C_MORE)
T.mcq("B1.1", "Choose the correct option: Your bag is the same ___ mine.", "as", ["like", "than"], C_AS)
T.gap("A2.1", "An elephant is ___ than a horse. (big)", "bigger", ex("*big → bigger*: one vowel + one consonant: double the consonant.", "*big → bigger*: viens patskanis + viens līdzskanis: līdzskani dubulto."))
T.gap("A2.2", "This is the ___ day of the year. (hot)", "hottest", C_EST)
T.gap("A2.2", "My new flat is ___ than the old one. (comfortable)", "more comfortable", C_MORE)
T.gap("B1.1", "Your English is getting ___ and ___. (good)", "better / better", ex("*getting better and better* = it improves all the time.", "*getting better and better* = kļūst arvien labāks."))
T.text("B1.1", "Correct the mistake: She is more older than her husband.", "She is older than her husband.", ex("Not *more* and *-er* together: *older.*", "Nekad *more* un *-er* kopā: *older.*"))
T.text("A2.2", "Correct the mistake: He is taller that me.", "He is taller than me.", C_ER)
T.order("A2.2", "this bag is heavier than that one", why=ex("*heavy → heavier*: *-y* → *-ier*.", "*heavy → heavier*: *-y* → *-ier*."))

# ── Modal verbs ──
M_MUSTNT = ex("*mustn't* = it is not allowed: *You mustn't smoke here.*", "*mustn't* = nedrīkst: *You mustn't smoke here.*")
M_BASE = ex("Modal verbs + base verb, no *-s*, no *to*: *She can speak…*", "Modālie darbības vārdi + pamatforma, bez -s un bez *to*: *She can speak…*")
M_DONT = ex("*don't / doesn't have to* = it is not necessary: *You don't have to pay.*", "*don't / doesn't have to* = nav vajadzīgs: *You don't have to pay.*")
M_SHOULD = ex("*should* + base verb = advice: *You should go to bed.*", "*should* + pamatforma = padoms: *You should go to bed.*")
M_HAD = ex("*must* has no past: use *had to*: *I had to work late.*", "*must* nav pagātnes formas: lieto *had to*: *I had to work late.*")
M_HAS = ex("*have to* changes like a normal verb: *he has to.*", "*have to* mainās kā parasts darbības vārds: *he has to.*")
T = Topic("Modal verbs: can, should, must, have to", mcq_b=2, text_b=3, mcq=M_BASE, bank=M_BASE, gap=M_BASE, text=M_BASE, order=M_BASE, match=M_BASE)
T.mcq("A2.1", "Choose the correct option: You ___ smoke in the hospital.", "mustn't", ["don't must", "not must"], M_MUSTNT)
T.mcq("A2.1", "Choose the correct option: She ___ speak three languages.", "can", ["cans", "can to"], M_BASE, b=1)
T.mcq("A2.2", "Choose the correct option: The museum is free. You ___ pay.", "don't have to", ["haven't to", "not have to"], M_DONT)
T.mcq("A2.2", "Choose the correct option: You look tired. You ___ go to bed.", "should", ["should to", "shoulds"], M_SHOULD)
T.mcq("B1.1", "Choose the correct option: I ___ work late yesterday.", "had to", ["must", "have to"], M_HAD)
T.gap("A2.2", "Use the present simple: My brother ___ get up at five for work. (have to)", "has to", M_HAS)
T.gap("A2.2", "We ___ be late. The film starts at eight. (must / not)", "mustn't | must not", M_MUSTNT)
T.gap("A2.2", "She ___ come to the meeting. It's not necessary. (have to / not)", "doesn't have to | does not have to", M_DONT)
T.text("A2.2", "Make it negative with don't have to: You have to bring food.", "You don't have to bring food. | You do not have to bring food.", M_DONT)
T.text("B1.1", "Correct the mistake: I will can help you tomorrow.", "I will be able to help you tomorrow. | I'll be able to help you tomorrow.", ex("No *will can*: *will be able to.*", "Nav *will can*: *will be able to.*"))
T.text("A2.2", "Correct the mistake: You should to see a doctor.", "You should see a doctor.", M_SHOULD)
T.order("A2.1", "we should leave before six", why=M_SHOULD)

